// Generated by `pnpm nx g @app/generators:action diagnostics.bundle`. Requests go through the real router
// with createTestEngine().inject. They fail until createDiagnosticsBundleAction is implemented; do not weaken them.
import { diagnosticsBundle } from '@app/contracts';
import { createRoleAuthorizer } from '@app/kernel';
import {
  FAKE_FILE_TOKEN,
  createDiagnosticsBundleAction,
  createOpsFakeDeps,
} from '@app/svc-ops';
import { afterEach, describe, expect, it } from 'vitest';

import { createTestEngine, type TestEngine } from '../create-test-engine.ts';

const subject = () => createDiagnosticsBundleAction(createOpsFakeDeps());
const def = diagnosticsBundle;
const KEY = 'generated-spec-key-0001';
let engine: TestEngine;

afterEach(async () => {
  await engine.close();
});

describe('POST /diagnostics/bundle', () => {
  it('GP-1 the route runs diagnostics.bundle and answers in the shape of the contract', async () => {
    engine = createTestEngine({ actions: [subject()] });
    const answer = await engine.inject({
      method: 'POST',
      path: '/diagnostics/bundle',
      payload: { fileToken: FAKE_FILE_TOKEN },
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(200);
    expect(def.output.safeParse(answer.json()).success).toBe(true);
  });

  it('GP-2 a request without the launch token is refused and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'POST',
      path: '/diagnostics/bundle',
      authenticated: false,
    });

    expect(answer.statusCode).toBe(401);
    expect(engine.audit.attempts).toEqual([]);
  });

  it('GP-3 a caller that does not hold diagnostics.export gets 403 and nothing runs', async () => {
    engine = createTestEngine({
      actions: [subject()],
      authorizer: createRoleAuthorizer({}),
    });
    const answer = await engine.inject({
      method: 'POST',
      path: '/diagnostics/bundle',
      payload: { fileToken: FAKE_FILE_TOKEN },
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(403);
    expect(answer.json()).toMatchObject({ code: 'FORBIDDEN_RBAC' });
    expect(engine.audit.attempts).toEqual([]);
    expect(engine.writeCalls).toEqual([]);
  });

  it('GP-4 input that breaks the contract is a 400 Problem and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });
    const answer = await engine.inject({
      method: 'POST',
      path: '/diagnostics/bundle',
      payload: { fileToken: FAKE_FILE_TOKEN, unexpected: true },
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(400);
    expect(answer.json()).toMatchObject({ code: 'VALIDATION_FAILED' });
    expect(engine.audit.attempts).toEqual([]);
  });

  it('GP-5 another method on the same path is 405', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'GET',
      path: '/diagnostics/bundle',
    });

    expect(answer.statusCode).toBe(405);
    expect(answer.headers.allow).toBe('POST');
  });
});
